use vstd::prelude::*;

verus! {
    fn contains_z(s: &str) -> (result: bool)
        ensures
            result == (exists |i: nat| 0 <= i < s.len() as nat && (s.chars().nth(i as usize) == Some('z') || s.chars().nth(i as usize) == Some('Z'))),
    {
        let len = s.chars().count() as nat; // Get the character count
        let mut idx: nat = 0; // Initialize index
        let mut found: bool = false; // Initialize found flag

        while idx < len
            invariant
                0 <= idx <= len,
                found == (exists |j: nat| 0 <= j < idx && (s.chars().nth(j as usize) == Some('z') || s.chars().nth(j as usize) == Some('Z'))),
            decreases len - idx,
        {
            if s.chars().nth(idx as usize) == Some('z') || s.chars().nth(idx as usize) == Some('Z') {
                found = true; // Set found to true if 'z' or 'Z' is found
            }
            idx = idx + 1; // Move to the next character
        }

        found // Return the result
    }
}
